// AR wearability index — record JAH-GPCS-ARGLASSES-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"fov_deg": 30, "brightness_nits": 1000, "weight_g": 40};
var value = (m.fov_deg*m.brightness_nits/m.weight_g);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-ARGLASSES-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-ARGLASSES-000001|' + value.toFixed(2) + ' wearability index');

